def var_eq(target, desc, pairs):
    return {"target_node": target, "description": desc, "condition": {"logic": "or", "conditions": [
        {"variable": v, "operator": "equals", "operand": o} for v, o in pairs]}}


def var_gt(target, desc, pairs):
