    lines.append('Any other day (for example ' + say(nextbd(nb)) + ' or a weekend) or any time before 10:00 or after 19:00 is OUTSIDE the window.')
    vars['callback_facts'] = '\n'.join(lines)
    vars['setup_state'] = 'ok'
except Exception:
