    m = re.match(r'\s*(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2}))?', raw)
    t = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return t, int(m.group(4) or 0), int(m.group(5) or 0)
'''

